INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9668, 72091, 'tt0059887', NULL, 'Voyage to the Prehistoric Planet', 'Voyage to the Prehistoric Planet', 'movie', 1965, 'https://image.tmdb.org/t/p/w500/3Zpax52NVEyf8nIcKlaWgGa6kb8.jpg', 'https://image.tmdb.org/t/p/original/prioHI5Z8BtN41QqZFd7frCp4Dp.jpg', 'In 2020, after the colonization of the moon, the spaceships Vega, Sirius and Capella are launched from Lunar Station 7. They are to explore Venus under the command of Professor Hartman, but an asteroid collides and explodes Capella. The leader ship Vega stays orbiting and sends the astronauts Kern and Sherman with the robot John to the surface of Venus, but they have problems with communication with Dr. Marsha Evans in Vega. The Sirius lands in Venus and Commander Brendan Lockhart, Andre Ferneau and Hans Walter explore the planet and are attacked by prehistoric animals. They use a vehicle to seek Kern and Sherman while collecting samples from the planet. Meanwhile John helps the two cosmonauts to survive in the hostile land.  Re-edited version of Soviet sci-fi  Planet of Storms (1962) by Pavel Klushantsev, dubbed into English with additional scenes.', NULL, NULL, 1.4324, 4.1, 0, 10.05, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9669, 22726, 'tt0054950', NULL, 'Battle of the Worlds', 'Il pianeta degli uomini spenti', 'movie', 1961, 'https://image.tmdb.org/t/p/w500/pB0PFki9xYEg0xnPCczT7wjQOTT.jpg', 'https://image.tmdb.org/t/p/original/6TLDBIHpFNNOfItGsSqLLcyMLWJ.jpg', 'A stray planet on a collision course with Earth instead takes orbit around our blue marble. What seems like a dead planet suddenly launches a fleet of flying saucers which attack our space fleets.', NULL, NULL, 1.1736, 4.595, 0, 10.05, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9670, 34276, 'tt0058100', NULL, 'First Men in the Moon', 'First Men in the Moon', 'movie', 1964, 'https://image.tmdb.org/t/p/w500/q2Ee1fUretsxTvNrobQzeVYbq22.jpg', 'https://image.tmdb.org/t/p/original/ispyRJVbcB3c9y6AhuZdbgMuzi.jpg', 'The world is delighted when a spacecraft containing a crew made up of the world''s astronauts lands on the moon, but are shocked when the astronauts discover an old British flag and a document declaring that the moon is taken for Queen Victoria proving that the astronauts were not the first men on the moon.', NULL, NULL, 2.7513, 6.3, 0, 10.05, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9671, 29290, 'tt0064393', NULL, 'The Green Slime', 'The Green Slime', 'movie', 1968, 'https://image.tmdb.org/t/p/w500/3MWnOwcLeySNqPtHpxqr7bJTZE5.jpg', 'https://image.tmdb.org/t/p/original/fLrntTx2ta90QhnMZpMnuhKxdTM.jpg', 'A giant asteroid is heading toward Earth so some astronauts disembark from a nearby space station to blow it up. The mission is successful, and they return to the station unknowingly bringing back a gooey green substance that mutates into one-eyed tentacled monsters that feed off electricity. Soon the station is crawling with them, and people are being zapped left and right!', NULL, NULL, 2.5927, 5.3, 0, 10.05, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
