INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9688, 419546, 'tt6156350', NULL, 'HyperNormalisation', 'HyperNormalisation', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/tTqI2xoB7cGO7HASB22Sss6x44J.jpg', 'https://image.tmdb.org/t/p/original/54HEQPoD7zWGGaCusDnDBG3aCFO.jpg', 'We live in a world where the powerful deceive us. We know they lie. They know we know they lie. They do not care. We say we care, but we do nothing, and nothing ever changes. It is normal. Welcome to the post-truth world. How we got to where we are now…', NULL, NULL, 2.147, 7.431, 0, 1.05, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9689, 355020, 'tt4908644', NULL, 'Winter on Fire: Ukraine''s Fight for Freedom', 'Winter on Fire: Ukraine''s Fight for Freedom', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/xGKMWhYsK3OxQ6ceqMnvXBfFd7G.jpg', 'https://image.tmdb.org/t/p/original/nhjWUf4wXsWZY9hKR1EoQOhjued.jpg', 'Over 93 days in Ukraine, what started as peaceful student demonstrations became a violent revolution and full-fledged civil rights movement.', NULL, NULL, 1.9127, 7.873, 0, 2.0, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9690, 524369, 'tt8110232', NULL, 'The Many Saints of Newark', 'The Many Saints of Newark', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/1UkbPQspPbq1FPbFP4VV1ELCfSN.jpg', 'https://image.tmdb.org/t/p/original/eA55xGHQMWHzpK4cANUFCUwUaYF.jpg', 'Young Anthony Soprano is growing up in one of the most tumultuous eras in Newark, N.J., history, becoming a man just as rival gangsters start to rise up and challenge the all-powerful DiMeo crime family. Caught up in the changing times is the uncle he idolizes, Dickie Moltisanti, whose influence over his nephew will help shape the impressionable teenager into the all-powerful mob boss, Tony Soprano.', NULL, NULL, 6.2302, 6.3, 0, 1.0, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9691, 264166, 'tt3576060', NULL, 'Point and Shoot', 'Point and Shoot', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/6hUKnGZTVK8Hyx1mMluX0qMMlac.jpg', 'https://image.tmdb.org/t/p/original/sSjyXL9xngmHQXtiOO6xOS3NfGr.jpg', 'At first glance, Matthew VanDyke—a shy Baltimore native with a sheltered upbringing and a tormenting OCD diagnosis—is the last person you’d imagine on the front lines of the 2011 Libyan revolution. But after finishing grad school and escaping the U.S. for "a crash course in manhood," a winding path leads him just there. Motorcycling across North Africa and the Middle East and spending time as an embedded journalist in Iraq, Matthew lands in Libya, forming an unexpected kinship with a group of young men who transform his life. Matthew joins his friends in the rebel army against Gaddafi, taking up arms (and a camera). Along the way, he is captured and held in solitary confinement for six terrifying months.', NULL, NULL, 0.8558, 6.389, 0, 1.0, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9692, 91487, 'tt0070959', NULL, 'State of Siege', 'État de siège', 'movie', 1972, 'https://image.tmdb.org/t/p/w500/yEH5yjGFgcEmS36XhFzIblQF0fJ.jpg', 'https://image.tmdb.org/t/p/original/2UoQWAxqhrP1iKhoWU4TzGO3FlT.jpg', 'Assigned to South America, US official Philip Michael Santore is employed by a counterinsurgency agency. His position makes him a target for a local band of guerrillas, and, before long, Santore is kidnapped. As a prisoner, he undergoes interrogation, shedding light on the violent situation in the country. Once the insurgents are done with their questioning, they must decide whether Santore lives or dies.', NULL, NULL, 2.6394, 7.158, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9693, 46101, 'tt0923869', NULL, 'United Red Army', '実録・連合赤軍 あさま山荘への道程', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/isCKuGp0M3FmxAhDGgV8YW0i46H.jpg', 'https://image.tmdb.org/t/p/original/htAjzpebmCfvEZ94pEf2YRA1LtR.jpg', 'Two of the most radical student groups form the United Red Army (URA) and head into the mountains to conduct a training camp. Ideology devolves into despotism, and the URA''s leaders begin to arbitrarily persecute their followers, a harrowing ordeal that culminates in violence and murder.', NULL, NULL, 1.5466, 6.391, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9694, 4790, 'tt0071890', NULL, 'The Nada Gang', 'Nada', 'movie', 1974, 'https://image.tmdb.org/t/p/w500/wxxNqUgtpQPCFS8Bkg50olhsBFA.jpg', 'https://image.tmdb.org/t/p/original/qLnZ9U1jiAIXVWoLLGF8DAiKbq2.jpg', 'Nada, named after a gang of Spanish anarchists, is a small, confused band of French terrorists. They kidnap the American ambassador after one of his regular visits to an exclusive brothel. The gang starts to quarrel amongst themselves as to the diplomat''s fate, while the police purge suspects in their attempts to destroy the Nada faction. As the violence escalates on both sides, the States and the terrorists are forced to use one another''s methods in an increasingly desperate and relentless conflict.', NULL, NULL, 1.6822, 6.048, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9695, NULL, NULL, 14362, 'Detroit: Become Human', 'Detroit: Become Human', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6mzf.jpg', NULL, 'Detroit: Become Human is an interactive narrative adventure game developed by Quantic Dream and released in 2018. Set in a near-future Detroit where androids serve humans, the story follows three android protagonists—Kara, Connor, and Markus—who shape the city’s fate through their choices. Gameplay combines exploration, dialogue interactions, and quick-time events, with branching storylines and multiple endings. The narrative explores themes of artificial intelligence, freedom, and morality.', 'https://www.igdb.com/games/detroit-become-human--1', '["PlayStation 4", "PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
