INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9703, 69316, 'tt6488862', NULL, 'Eternal Love', '三生三世十里桃花', 'tv', 2017, 'https://image.tmdb.org/t/p/w500/paeDktO7Bx2lmv9mEDiHtneoYrF.jpg', 'https://image.tmdb.org/t/p/original/wLbQlNHDBYTbrsrffeYPG9KlCLy.jpg', 'Three hundred years ago, Bai Qian stood on the Zhu Xian Terrace, turned around and jumped off without regret. Ye Hua stood by the bronze mirror to witness with his own eyes her death. Three hundred years later, in the East Sea Dragon Palace, the two meet unexpectedly. Another lifetime another world, after suffering betrayal Bai Qian no longer feels anything, yet she can''t seem to comprehend Ye Hua''s actions. Three lives three worlds, her and him, are they fated to love again?', NULL, NULL, 10.6038, 7.7, 0, 1.16, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
