INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9714, 14657, 'tt0074035', NULL, 'The Onedin Line', 'The Onedin Line', 'tv', 1971, 'https://image.tmdb.org/t/p/w500/wdMppd359jiZMz4tO5qPVLG1IF6.jpg', 'https://image.tmdb.org/t/p/original/hC7FyjPrGv7kas0q4t6nrmxSm81.jpg', 'The Onedin Line is a BBC television drama series which ran from 1971 to 1980. The series was created by Cyril Abraham.

The series is set in Liverpool from 1860 to 1886 and deals with the rise of a shipping line, the Onedin Line, named after its owner James Onedin. Around this central theme are the lives of his family, most notably his brother and partner, shop owner Robert, and his sister Elizabeth, giving insight into the lifestyle and customs at the time, not only at sea, but also ashore. The series also illustrates some of the changes in business and shipping, such as from wooden to steel ships and from sailing ships to steam ships. It shows the role that ships played in affairs like international politics, uprisings and the slave trade.', NULL, NULL, 10.1, 7.0, 0, 5.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
