INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9748, 279997, 'tt2536124', NULL, 'I Survived a Zombie Holocaust', 'I Survived a Zombie Holocaust', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/oawjYX3KXRS6l8qSFf71ttScHB3.jpg', 'https://image.tmdb.org/t/p/original/8pSU7Q0NgKedMFrvrXqvO9a4YDa.jpg', 'From the land of early Peter Jackson comes another Braindead movie in bad taste. It’s the third day of shooting the low budget horror ‘Tonight They Come’ on location in the wilds of New Zealand. Director SMP is already beside himself having to work with a self-obsessed leading man and a bimbo actress when into his line of fire comes a new runner, wannabe screenwriter Wesley Pennington. Clearly an accident-prone nerd, Wesley nevertheless tries his best to fit in with the crazed cast and demented crew while falling head over heels for Susan, the set caterer. But something nasty has entered the local water supply and suddenly the zombie extras start acting like genuine members of the living dead, gore stunts looks even more authentic and actual severed limbs fly. Reel life turns real as Wesley attempts to save the day while ensuring his latest script will get made.', NULL, NULL, 1.0637, 5.14, 0, 1.12, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
