INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9783, NULL, NULL, 1956, 'Alone in the Dark', 'Alone in the Dark', 'game', 1992, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co82bd.jpg', NULL, 'Alone in the Dark is one of the first survival horror games and the first to utilize 3D models superimposed on pre-rendered backgrounds, which would become a key inspiration for upcoming horror games at the time, like the Resident Evil franchise. The player can use various weapons, such as pistol, rifle, swords and knives, though it is possible to kill most enemies with melee attacks. Some opponents can be beaten by solving a particular puzzle, while a significant number of opponents cannot be killed at all or only with certain weapons.', 'https://www.igdb.com/games/alone-in-the-dark', '["Acorn Archimedes", "PC-9800 Series", "PC (Microsoft Windows)", "3DO Interactive Multiplayer", "Mac", "DOS", "FM Towns"]', NULL, NULL, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
