INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9785, 82452, 'tt9018736', NULL, 'Avatar: The Last Airbender', 'Avatar: The Last Airbender', 'tv', 2024, 'https://image.tmdb.org/t/p/w500/lzZpWEaqzP0qVA5nkCc5ASbNcSy.jpg', 'https://image.tmdb.org/t/p/original/aVvRQJ2Ckhlym4uh0YGc166CUoP.jpg', 'A young boy known as the Avatar must master the four elemental powers to save a world at war — and fight a ruthless enemy bent on stopping him.', NULL, NULL, 84.698, 7.787, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9786, 60831, 'tt3398976', NULL, 'Knights of Sidonia', 'シドニアの騎士', 'tv', 2014, 'https://image.tmdb.org/t/p/w500/tGTx2Ec25bWjtanJe7D5vUmQUkA.jpg', 'https://image.tmdb.org/t/p/original/dDDGlVK9cABrVskRUjFrqpVzJgm.jpg', 'An alien race called Gauna has destroyed Earth. leaving humanity struggling to survive aboard the spaceship Sidonia. Even though it’s been a century since the last encounter with the Gauna, military service is mandatory. For Nagate Tanikaze, whose grandfather secretly hid him in the forgotten bowels of Sidonia, it’s a strange new world as he’s forced to come to the surface. Yet his recruitment comes just in time, for the Gauna have suddenly reappeared.', NULL, NULL, 11.5794, 7.686, 0, 2.05, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9787, NULL, NULL, 333894, 'Metal Garden', 'Metal Garden', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9h5w.jpg', NULL, 'Travel through an overgrown megastructure, and discover what lies beyond it. Metal Garden is a short, atmospheric singleplayer FPS game.', 'https://www.igdb.com/games/metal-garden', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.02, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9788, 74185, 'tt7474942', NULL, 'Girls'' Last Tour', '少女終末旅行', 'tv', 2017, 'https://image.tmdb.org/t/p/w500/hEtkOaiI759zfO6YT4PiNmrbtv4.jpg', 'https://image.tmdb.org/t/p/original/5ZeU6YQGHMd0jqQCxsE9SpshQw2.jpg', 'Civilization is dead, but Chito and Yuuri are still alive. So they hop aboard their beloved Kettenkrad motorbike and aimlessly wander the ruins of the world they once knew. Day after hopeless day, they look for their next meal and fuel for their ride. But as long as the two are together, even an existence as bleak as theirs has a ray or two of sunshine in it, whether they''re sucking down their fill of soup or hunting for machine parts to tinker with. For two girls in a world full of nothing, the experiences and feelings the two share give them something to live for.', NULL, NULL, 11.3154, 8.0, 0, 1.02, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9789, NULL, NULL, 612, 'Beneath a Steel Sky', 'Beneath a Steel Sky', 'game', 1994, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ciz.jpg', NULL, 'Beneath a Steel Sky is a cyberpunk, point and click, adventure game. You assume the role of Robert Foster and embark on a quest to make the world a better place, along with your robot companion Joey.', 'https://www.igdb.com/games/beneath-a-steel-sky', '["Amiga CD32", "Linux", "PC (Microsoft Windows)", "iOS", "Mac", "DOS", "Amiga"]', NULL, NULL, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9790, 13763, 'tt0087957', NULL, 'Purple Rain', 'Purple Rain', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/vkQmzaSuDj8QyXmwNhCceCAmwUe.jpg', 'https://image.tmdb.org/t/p/original/s3WFrpZV1QIo8Aao2TaAI5ERUTO.jpg', 'A victim of his own anger, the Kid is a Minneapolis musician on the rise with his band, the Revolution, escaping a tumultuous home life through music. While trying to avoid making the same mistakes as his truculent father, the Kid navigates the club scene and a rocky relationship with a captivating singer, Apollonia. But another musician, Morris, looks to steal the Kid''s spotlight -- and his girl.', NULL, NULL, 4.2604, 6.689, 0, 11.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9791, 288, 'tt0044706', NULL, 'High Noon', 'High Noon', 'movie', 1952, 'https://image.tmdb.org/t/p/w500/qETSMQ4IXBSAS409Z9OL0ppXWTW.jpg', 'https://image.tmdb.org/t/p/original/raYHhtIDyh3qDS6WdyRzeqjLyIK.jpg', 'Will Kane, the sheriff of a small town in New Mexico, learns a notorious outlaw he put in jail has been freed, and will be arriving on the noon train. Knowing the outlaw and his gang are coming to kill him, Kane is determined to stand his ground, so he attempts to gather a posse from among the local townspeople.', NULL, NULL, 7.6114, 7.7, 0, 11.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9792, 9429, 'tt0120770', NULL, 'A Night at the Roxbury', 'A Night at the Roxbury', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/7oZ5xE4AL4D5EbeQUaoRxahgzJX.jpg', 'https://image.tmdb.org/t/p/original/ygc5qt7mxtsPljY2W9LAbZWFDGb.jpg', 'Despite being well into adulthood, brothers Doug and Steve Butabi still live at home and work in the flower shop owned by their dad. They exist only to hit on women at discos, though they''re routinely unsuccessful until a chance run-in with Richard Grieco gets them inside the swank Roxbury club. Mistaken for high rollers, they meet their dream women, Vivica and Cambi, and resolve to open a club of their own.', NULL, NULL, 5.8585, 6.539, 0, 11.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
