INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9794, NULL, NULL, 10662, 'Disney''s Tarzan', 'Disney''s Tarzan', 'game', 1999, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co55sp.jpg', NULL, 'The player takes control of the eponymous Tarzan who ultimately has to save his home, the jungle, from Clayton, a hunter for gorillas. Tarzan starts up as a child learning the skills of the apes. The game has 3 difficulties: easy, medium and hard. In the easy and medium difficulties, little Tarzan gets tips from his friend Turk. Tarzan''s enemies are monkeys, baboons, eagles, and different animals, including some humans and Clayton.', 'https://www.igdb.com/games/disneys-tarzan', '["PlayStation 3", "Nintendo 64", "PC (Microsoft Windows)", "PlayStation", "PlayStation Portable"]', NULL, NULL, 0, 8.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9795, 25379, 'tt0313300', NULL, 'The Blue Butterfly', 'The Blue Butterfly', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/wuKQhiIrPPhY6DDOdYYrsWoVcK9.jpg', 'https://image.tmdb.org/t/p/original/iSfEs4TSZ0ECPukWNPw5EoBws3A.jpg', 'Based on a true story, The Blue Butterfly tells the story of a terminally ill 10-year-old boy whose dream is to catch the most beautiful butterfly on Earth, the mythic and elusive Blue Morpho. His mother persuades a renowned entomologist to take them on a trip to the jungle to search for the butterfly, leading to an adventure that will transform their lives', NULL, NULL, 1.2151, 7.028, 0, 10.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
