INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9799, 91133, 'tt0166321', NULL, 'The Real Macaw', 'The Real Macaw', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/ubZOcacH6kqr3tiox4BNtgWVEQ7.jpg', 'https://image.tmdb.org/t/p/original/xxWIB7YrQkhe1QS8Suwt00ltWxK.jpg', 'An ancient talking macaw named Mac becomes the saving grace for an elderly man threatened with a nursing home, when it is discovered that the talking bird knows the whereabouts of a buried treasure from its days with a pirate. His grandson decides to go off on the hunt only to discover that a resort now exists where the treasure is buried.', NULL, NULL, 1.7203, 6.0, 0, 8.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9800, 9343, 'tt0083946', NULL, 'Fitzcarraldo', 'Fitzcarraldo', 'movie', 1982, 'https://image.tmdb.org/t/p/w500/oBCnYEKcg1rMhr5JjDnrRpilvDd.jpg', 'https://image.tmdb.org/t/p/original/46iMqI1qzAtnXJxGRNCFwYNYqOo.jpg', 'Fitzcarraldo is a dreamer who plans to build an opera house in Iquitos, in the Peruvian Amazon, so, in order to finance his project, he embarks on an epic adventure to collect rubber, a very profitable product, in a remote and unexplored region of the rainforest.', NULL, NULL, 5.9875, 7.593, 0, 10.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9801, 9093, 'tt0240510', NULL, 'The Four Feathers', 'The Four Feathers', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/bfmpeRr9LTXzBC2dpC89FE5uavK.jpg', 'https://image.tmdb.org/t/p/original/2IojDzEWedVbre8KZhZPMoP5az4.jpg', 'A young British officer resigns his post when he learns of his regiment''s plan to ship out to the Sudan for the conflict with the Mahdi. His friends and fiancée send him four white feathers as symbols of what they view as his cowardice. To redeem his honor, he disguises himself as an Arab and secretly saves their lives.', NULL, NULL, 4.8939, 6.638, 0, 2.035, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9802, 1207162, 'tt25868520', NULL, 'Rise of the Conqueror', 'Rise of the Conqueror', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/9cRE0DsM6CNIiY9Ah3cd8oc3n1Y.jpg', 'https://image.tmdb.org/t/p/original/9gWrxuOJeArUbvnqrZALSjhPv9Y.jpg', 'In the 14th-century, as the Silk Road crumbles and rival factions tear the land apart, fearless warrior Timur emerges from exile. Stripped of everything, he fights to unite the fractured kingdoms, using strategy and sheer will to carve an empire from chaos. Undefeated in battle and widely regarded as one of history’s greatest military leaders and tacticians, not to mention one of its most brutal, Timur would found the Timurid Empire, which ruled over modern-day Afghanistan, Iran and Central Asia.', NULL, NULL, 14.7728, 5.974, 0, 1.06, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
