INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9836, 36584, 'tt0308411', NULL, 'Interview with the Assassin', 'Interview with the Assassin', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/yCEP43DIYqx8NM9ttcmgSnxScRI.jpg', 'https://image.tmdb.org/t/p/original/4OI84heveHnK3BSUN3AtXsIXTWh.jpg', 'Out of work TV cameraman Ron Kobelski is approached by his formerly reclusive neighbor Walter Ohlinger. Ohlinger claims that he was the mysterious "second gunman" that shot and killed President Kennedy. Ohlinger has kept quiet all these years, but has decided to tell his story now that he has been diagnosed with terminal cancer. Kobelski is skeptical of his neighbor''s story, after his investigations provide ambiguous answers. His attitude changes, however, after he receives threatening messages on his answering machine, and spots shadowy figures in his backyard. Is Ohlinger telling the truth? Or is there a bigger conspiracy at work?', NULL, NULL, 0.9772, 5.462, 0, 1.33, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
