INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9892, 829732, 'tt10106394', NULL, 'Forest for the Trees', 'Forest for the Trees', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/4goHo1mCrKMj39wMJvVs9g1Lo3i.jpg', NULL, 'Award-winning war photographer Rita Leistner goes back to her roots as a tree planter in the wilderness of British Columbia, offering an inside take on the grueling, sometimes fun and always life-changing experience of restoring Canada’s forests. Leistner, who has photographed some of the world’s most dangerous places, credits the challenge of tree-planting for her physical and mental endurance. In Forest for the Trees, her first feature film, she revisits her past to share the lessons she learned. The film introduces us to everyday life on the “cut-block” and the brave souls who fight through rough terrains and work endless hours to bring our forests to life. The rugged BC landscape comes to life magically in Leistner’s photography, while the quirky characters and nuggets of wisdom shared around the campfire tell a sincere story of community.', NULL, NULL, 0.9832, 0.0, 0, 9.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9893, 1004642, 'tt18469872', NULL, 'Amanda', 'Amanda', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/bGWPFd71ygELIkPf9SjcOBkLAZY.jpg', 'https://image.tmdb.org/t/p/original/pSNUZGnXUd3DDb1AdvQh2W1Jbsp.jpg', 'Amanda, 24, lives mostly isolated and has never had any friends, even if it''s the thing she wants the most. Amanda chooses her new mission as to convince her childhood friend to believe that they are still best friends.', NULL, NULL, 2.1731, 6.532, 0, 8.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9894, 44770, 'tt1294161', NULL, 'The Exploding Girl', 'The Exploding Girl', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/xRJ4wgDtxwoDzKjVRjZ457kf85f.jpg', NULL, 'On a summer break from college, Ivy, a young epileptic woman, struggles to balance her feelings for her fledgling boyfriend while her friend Al crashes with her for the season.', NULL, NULL, 1.1446, 5.988, 0, 9.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9895, 10867, 'tt0213847', NULL, 'Malena', 'Malèna', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/3OyQTl0IGkbnjDxd3MhztfPE34g.jpg', 'https://image.tmdb.org/t/p/original/vadUKKQixxOKWkcuZ1SUEoBQeVG.jpg', '12-year-old Renato experiences three significant events on the same day: the beginning of the Second World War, getting a bike, and witnessing the arrival of the gorgeous Malèna. Through his eyes, we see the curse of beauty and loneliness of Malena, whose husband is presumed dead, and, through his soul, we see his love for her.', NULL, NULL, 26.1606, 7.547, 0, 9.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9896, 1573, 'tt0099423', NULL, 'Die Hard 2', 'Die Hard 2', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/ybki0UWO3OPhaM6MSniuKC7sy1R.jpg', 'https://image.tmdb.org/t/p/original/cDtefl7KGnKrDziEUXetMnztvqr.jpg', 'One year after his heroics in Los Angeles, John McClane is an off-duty cop who is the wrong guy in the wrong place at the wrong time. On a snowy Christmas Eve, as he waits for his wife''s plane to land at Washington Dulles International Airport, terrorists take over the air traffic control system in a plot to free a South American army general and drug smuggler being flown into the US to face drug charges. It''s now up to McClane to take on the terrorists, while coping with an inept airport police chief, an uncooperative anti-terrorist squad, and the life of his wife and everyone else trapped in planes circling overhead.', NULL, NULL, 19.0326, 6.97, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9897, 13673, 'tt0388419', NULL, 'Christmas with the Kranks', 'Christmas with the Kranks', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/q866vL3KhAjbkZH1enT7AoxmRHx.jpg', 'https://image.tmdb.org/t/p/original/lcFar2tdF9Lir12R0K3Dvw6uABu.jpg', 'When their only daughter Blair leaves the family nest, Luther and Nora Krank decide to book an island cruise to beat the yuletide blues and just skip the holidays. But their decision to boycott tradition has the whole neighborhood in an uproar, and when Blair calls on Christmas Eve to announce a surprise visit with her new fiancée, the Kranks have just twelve hours to perform a miracle and pull themselves and their neighbors together to throw the best celebration ever!', NULL, NULL, 5.8673, 6.163, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
