INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9914, 826, 'tt0050212', NULL, 'The Bridge on the River Kwai', 'The Bridge on the River Kwai', 'movie', 1957, 'https://image.tmdb.org/t/p/w500/7paXMt2e3Tr5dLmEZOGgFEn2Vo7.jpg', 'https://image.tmdb.org/t/p/original/dRHfCeAoJ6SsMffQ6lavNU9E55z.jpg', 'The classic story of English POWs in Burma forced to build a bridge to aid the war effort of their Japanese captors. British and American intelligence officers conspire to blow up the structure, but Col. Nicholson, the commander who supervised the bridge''s construction, has acquired a sense of pride in his creation and tries to foil their plans.', NULL, NULL, 7.2037, 7.82, 0, 11.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
