INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9916, 10971, 'tt0051994', NULL, 'A Night to Remember', 'A Night to Remember', 'movie', 1958, 'https://image.tmdb.org/t/p/w500/6fDhJAz6AuYWj3hAnvUL42Xlxfj.jpg', 'https://image.tmdb.org/t/p/original/gHWnnV2n9eS1aQKRmg6JSpj6bsC.jpg', 'The sinking of the Titanic is presented in a highly realistic fashion in this tense British drama. The disaster is portrayed largely from the perspective of the ocean liner''s second officer, Charles Lightoller. Despite numerous warnings about ice, the ship sails on, with Capt. Edward John Smith keeping it going at a steady clip. When the doomed vessel finally hits an iceberg, the crew and passengers discover that they lack enough lifeboats, and tragedy follows.', NULL, NULL, 3.7265, 7.645, 0, 11.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9917, 86382, 'tt1831804', NULL, 'The Stand', 'The Stand', 'tv', 2020, 'https://image.tmdb.org/t/p/w500/w6XiuRK5QQaLNmIqDRCWOpEcHwi.jpg', 'https://image.tmdb.org/t/p/original/b7MUOLzo9kxQRSjGHwp589HMdxI.jpg', 'In a world mostly wiped out by the plague and embroiled in an elemental struggle between good and evil, the fate of mankind rests on the frail shoulders of the 108-year-old Mother Abagail and a handful of survivors. Their worst nightmares are embodied in a man with a lethal smile and unspeakable powers: Randall Flagg, the Dark Man.', NULL, NULL, 10.4426, 6.798, 0, 11.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9918, 8992, 'tt0090103', NULL, 'The Sure Thing', 'The Sure Thing', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/a9cuohQn5kczi4htWZAZjEZvXkZ.jpg', 'https://image.tmdb.org/t/p/original/6E0GtHsx8335YHJE7dD9oL1gk9i.jpg', 'Gib, a beer-guzzling slob, and Alison, an uptight Ivy-Leaguer, are an unlikely duo stuck together on a cross-country trip during Christmas break. At first they get on each other''s nerves but, as time passes, they find their divergent natures complement each other. Now they need to realize what they''ve already found before it''s too late.', NULL, NULL, 4.4938, 6.53, 0, 11.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
