INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9920, 261, 'tt0051459', NULL, 'Cat on a Hot Tin Roof', 'Cat on a Hot Tin Roof', 'movie', 1958, 'https://image.tmdb.org/t/p/w500/5djZZECgqDGuSI1INmrdAcGRBb0.jpg', 'https://image.tmdb.org/t/p/original/nXAP7rUMno8DjBFqkM5IZlnpybm.jpg', 'An alcoholic ex-football player drinks his days away, having failed to come to terms with his sexuality and his real feelings for his football buddy who died after an ambiguous accident. His wife is crucified by her desperation to make him desire her: but he resists the affections of his wife. His reunion with his father—who is dying of cancer—jogs a host of memories and revelations for both father and son.', NULL, NULL, 3.9651, 7.6, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
