INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9930, 393559, 'tt2321405', NULL, 'My Life as a Zucchini', 'Ma vie de courgette', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/2uu8fIzl76C9MFiUQhjKYSLKVq.jpg', 'https://image.tmdb.org/t/p/original/lTOr8fcxlsLrGfe2lqZLCjhvrIH.jpg', 'After his mother’s death, Zucchini is befriended by a kind police officer, Raymond, who accompanies him to his new foster home filled with other orphans his age. There, with the help of his newfound friends, Zucchini eventually learns to trust and love as he searches for a new family of his own.', NULL, NULL, 4.0054, 7.789, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
