INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9933, 357, 'tt0395413', NULL, 'The Trap Door', 'The Trap Door', 'tv', 1986, 'https://image.tmdb.org/t/p/w500/jFDfQo3RjG3IZ4bLZeATLXBbo9g.jpg', 'https://image.tmdb.org/t/p/original/4kwdxGIP8bU9zFQkih8XN4j3hUD.jpg', 'The Trap Door is a claymation-style animated television series, originally shown in the United Kingdom in 1984. The plot revolves around both the daily lives and the misadventures of a group of monsters living in a castle. Although the emphasis was on humour and the show was marketed as a children''s programme but also for family entertainment, the show drew much from the genres of horror and dark fantasy. The show has since become a cult favourite and remains one of the most widely recognised kids'' shows of the 1980s. Digital children''s channel Pop started rerunning the show in 2010.', NULL, NULL, 3.5074, 7.714, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
