INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9950, 9442, 'tt0083798', NULL, 'Dead Men Don''t Wear Plaid', 'Dead Men Don''t Wear Plaid', 'movie', 1982, 'https://image.tmdb.org/t/p/w500/cwYwZBEE73PakUWzbICzxYKlXAz.jpg', 'https://image.tmdb.org/t/p/original/hhxrMW0WY30ulaCGMu5mVezktHQ.jpg', 'Juliet Forrest is convinced that the reported death of her father in a mountain car crash was no accident. Her father was a prominent cheese scientist working on a secret recipe. To prove it was murder, she enlists the services of private eye Rigby Reardon. He finds a slip of paper containing a list of people who are ''The Friends and Enemies of Carlotta''.', NULL, NULL, 3.0676, 6.65, 0, 2.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9951, 70917, 'tt1260587', NULL, 'The Scenesters', 'The Scenesters', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/kF1jb6BtIadRjFyflXgzstS0q0o.jpg', 'https://image.tmdb.org/t/p/original/ofJAJTtJgRGzvVhURUpAMRXmaTX.jpg', 'Someone is killing beautiful young Hipsters in East L.A. Charlie is a crime scene cleaner working for Aftershocks Inc. with a penchant for Sherlock Holmes type deduction. Wallace is an out-of-luck filmmaker working as a crime scene videographer. The detectives covering the murders are apathetic at best but with good names (Henry and Carlita, particularly Carlita). Good names, bad attitudes.', NULL, NULL, 1.1034, 4.9, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
