INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (9953, 9548, 'tt0098987', NULL, 'The Adventures of Ford Fairlane', 'The Adventures of Ford Fairlane', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/u6accimG7LmroR8WgNklEJS7oFq.jpg', 'https://image.tmdb.org/t/p/original/jbGbFD9DgGgrfDVyV8RVuKZjTcW.jpg', 'To the Los Angeles elite, Ford Fairlane is known as "Mr. Rock ''n'' Roll Detective." This loudmouthed ladies'' man serves an exclusive rock star clientele, who depend on his keen eye and smug discretion. So when a heavy-metal musician dies mid-concert, Fairlane is on the case before the lights come up. But things turn shocking when radio personality Johnny Crunch hires Fairlane to find a missing groupie mere hours before he is electrocuted live on air.', NULL, NULL, 3.5537, 6.122, 0, 1.01, '2026-08-12 02:31:31', '2026-08-12 02:31:31');
