UPDATE "recommendations" SET "tmdb_id"=11020, "imdb_id"='tt0073540', "igdb_id"=NULL, "title"='Picnic at Hanging Rock', "original_title"='Picnic at Hanging Rock', "media_type"='movie', "release_year"=1975, "poster_url"='https://image.tmdb.org/t/p/w500/7BAXwmFN4pZDNb9N6kzmAAwdssi.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/41Mlaj6wfjlF4wQaVH0tjfDXvMi.jpg', "overview"='In the early 1900s, Miranda attends a girls boarding school in Australia. One Valentine''s Day, the school''s typically strict headmistress treats the girls to a picnic field trip to an unusual but scenic volcanic formation called Hanging Rock. Despite rules against it, Miranda and several other girls venture off. It''s not until the end of the day that the faculty realizes the girls and one of the teachers have disappeared mysteriously.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5711, "vote_average"=7.233, "is_ambiguous"=0, "evidence_score"=3.99663888888888862e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-12 02:31:31' WHERE "id"=17;
