UPDATE "recommendations" SET "tmdb_id"=795, "imdb_id"='tt0120632', "igdb_id"=NULL, "title"='City of Angels', "original_title"='City of Angels', "media_type"='movie', "release_year"=1998, "poster_url"='https://image.tmdb.org/t/p/w500/iuzxpUjHsbQJXV3kB9ZAdCimM60.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pYl4YpepgRbr504D7ep58C5gMyF.jpg', "overview"='When a guardian angel – who invisibly watches over the citizens of Los Angeles – becomes captivated by a strong-willed heart surgeon, he ponders trading in his pure, otherworldly existence for a mortal life with his beloved. The couple embarks on a tender but forbidden romance spanning heaven and Earth.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.6565, "vote_average"=6.819, "is_ambiguous"=0, "evidence_score"=9.01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-12 02:31:31' WHERE "id"=306;
