UPDATE "recommendations" SET "tmdb_id"=1092, "imdb_id"='tt0041959', "igdb_id"=NULL, "title"='The Third Man', "original_title"='The Third Man', "media_type"='movie', "release_year"=1949, "poster_url"='https://image.tmdb.org/t/p/w500/rO2Fq0AZZx9obs52KJdx4mRE8p5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/rLLhOCgAjuvlKmjUqVb7P1UAbUI.jpg', "overview"='In postwar Vienna, Austria, Holly Martins, a writer of pulp Westerns, arrives penniless as a guest of his childhood chum Harry Lime, only to learn he has died. Martins develops a conspiracy theory after learning of a "third man" present at the time of Harry''s death, running into interference from British officer Major Calloway, and falling head-over-heels for Harry''s grief-stricken lover, Anna.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.8457, "vote_average"=7.9, "is_ambiguous"=0, "evidence_score"=1.28085714285714278e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-12 02:31:31' WHERE "id"=1151;
