UPDATE "recommendations" SET "tmdb_id"=975335, "imdb_id"='tt36456563', "igdb_id"=NULL, "title"='Magellan', "original_title"='Magalhães', "media_type"='movie', "release_year"=2025, "poster_url"='https://image.tmdb.org/t/p/w500/pmFeUueU7BWLVnHrYI1FD7VnxtH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/8nv5MUtEBMX4DDkrFkDhkppRxuD.jpg', "overview"='At the dawn of the modern era, Portuguese explorer Ferdinand Magellan leads an expedition under the Spanish crown in search of the first westward route to the Spice Islands. He embarks on a perilous journey across the uncharted Pacific, where his fleet faces starvation, mutiny, and the psychological toll of endless seas. Upon reaching the shores of Cebu, Magellan is pulled into a fatal conflict with the natives by his drive to spread Catholicism, culminating in his tragic doom.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.1589, "vote_average"=6.4, "is_ambiguous"=0, "evidence_score"=9.54, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-12 02:31:31' WHERE "id"=1766;
