UPDATE "recommendations" SET "tmdb_id"=80, "imdb_id"='tt0381681', "igdb_id"=NULL, "title"='Before Sunset', "original_title"='Before Sunset', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/4sW5XH9ZfYXpvFzev00S1IGAEbg.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/tcZi0LQc5iu2u6i5aOWyj9NBBvl.jpg', "overview"='Nine years later, Jesse travels across Europe giving readings from a book he wrote about the night he spent in Vienna with Celine. After his reading in Paris, Celine finds him, and they spend part of the day together before Jesse has to again leave for a flight. They are both in relationships now, and Jesse has a son, but as their strong feelings for each other start to return, both confess a longing for more.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.7426, "vote_average"=7.8, "is_ambiguous"=0, "evidence_score"=15.4675, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-12 02:31:31' WHERE "id"=1820;
