UPDATE "recommendations" SET "tmdb_id"=110416, "imdb_id"='tt1865505', "igdb_id"=NULL, "title"='Song of the Sea', "original_title"='Song of the Sea', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/16LQC6zpqB0l74mVWb93a2oMFnX.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mVLZvSe1Aa8CFKx0cInTamVZJrW.jpg', "overview"='The story of the last Seal Child’s journey home. After their mother’s disappearance, Ben and Saoirse are sent to live with Granny in the city. When they resolve to return to their home by the sea, their journey becomes a race against time as they are drawn into a world Ben knows only from his mother’s folktales. But this is no bedtime story; these fairy folk have been in our world far too long. It soon becomes clear to Ben that Saoirse is the key to their survival.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.1815, "vote_average"=7.985, "is_ambiguous"=0, "evidence_score"=2.23122222222222212e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-12 02:31:31' WHERE "id"=2508;
