UPDATE "recommendations" SET "tmdb_id"=38782, "imdb_id"='tt0086590', "igdb_id"=NULL, "title"='The Wind in the Willows', "original_title"='The Wind in the Willows', "media_type"='movie', "release_year"=1983, "poster_url"='https://image.tmdb.org/t/p/w500/Dgg7N0bukwmVJU2c1UtgxpdpDB.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/hhnzRodAKHCkIYoaOcN6GXQBM3g.jpg', "overview"='One spring, Mole decides that he can ignore the spring cleaning for a little longer, and begins a series of adventures with his new friend Rat. They go for a picnic on the riverbank, on a caravan expedition with Toad, until Toad switches allegiance to his new car and his reckless driving makes Mole and Rat search out Badger for help in curbing Toad''s profligate habits. But Toad gets away from them and gets a 20-year sentence from the magistrate for theft, reckless driving, and Gross Impertinence. While Toad works his wiles on the jailer''s daughter and escapes jail dressed as a washer woman, Badger tries to guard Toad Hall from the machinations of the Weasels and is badly beaten. And it requires a plan of attack and all four comrades to regain Toad Hall.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.675, "vote_average"=6.955, "is_ambiguous"=0, "evidence_score"=8.78000000000000113e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-12 02:31:31' WHERE "id"=2527;
