UPDATE "recommendations" SET "tmdb_id"=6878, "imdb_id"='tt0107131', "igdb_id"=NULL, "title"='Homeward Bound: The Incredible Journey', "original_title"='Homeward Bound: The Incredible Journey', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/el6dJEpK97OJRQiQhuiSGk2jkV5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xDwDhLtQnA7jK4f7DVkdeSvZnAp.jpg', "overview"='Before the Seavers leave for a family vacation to San Francisco, they drop off their pets -- Chance, an adventurous American bulldog; Shadow, a wise golden retriever; and Sassy, a cautious cat -- at a friend''s ranch. But when the animals start to worry that they''ve been left for good, the three embark together on a treacherous and thrilling journey to find their way back home through the California wilderness.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.1211, "vote_average"=6.992, "is_ambiguous"=0, "evidence_score"=1.67815384615384601e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-12 02:31:31' WHERE "id"=3312;
UPDATE "recommendations" SET "tmdb_id"=10762, "imdb_id"='tt0364751', "igdb_id"=NULL, "title"='Without a Paddle', "original_title"='Without a Paddle', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/bSQBfHDzyfzxrCLepjegVb5F8j8.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/vEEEKiUJOXmOJXW7X8P3kCgsm9p.jpg', "overview"='Three friends, whose lives have been drifting apart, reunite for the funeral of a fourth childhood friend. When looking through their childhood belongings, they discover a trunk which contained details on a quest their friend was attempting. It revealed that he was hot on the trail of the $200,000 that went missing with airplane hijacker D.B. Cooper in 1971. They decide to continue his journey, but do not understand the dangers they will soon encounter.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.5046, "vote_average"=5.644, "is_ambiguous"=0, "evidence_score"=9.014, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-12 02:31:31' WHERE "id"=3315;
UPDATE "recommendations" SET "tmdb_id"=4018, "imdb_id"='tt0096684', "igdb_id"=NULL, "title"='Quantum Leap', "original_title"='Quantum Leap', "media_type"='tv', "release_year"=1989, "poster_url"='https://image.tmdb.org/t/p/w500/ujIGP3e3V6kDQHRhjNYtUE3fHJi.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5TpptGoxVVght2n6oz8QJklmSTu.jpg', "overview"='Theorizing that one could time travel within his own lifetime, Dr. Sam Beckett stepped into the Quantum Leap accelerator and vanished... He woke to find himself trapped in the past, facing mirror images that were not his own and driven by an unknown force to change history for the better. His only guide on this journey is Al, an observer from his own time, who appears in the form of a hologram that only Sam can see and hear. And so Dr. Beckett finds himself leaping from life to life, striving to put right what once went wrong and hoping each time that his next leap will be the leap home.', "external_url"=NULL, "platforms"=NULL, "popularity"=45.2026, "vote_average"=8.017, "is_ambiguous"=0, "evidence_score"=5.52999999999999936e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-12 02:31:31' WHERE "id"=3321;
