UPDATE "recommendations" SET "tmdb_id"=652, "imdb_id"='tt0332452', "igdb_id"=NULL, "title"='Troy', "original_title"='Troy', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/a07wLy4ONfpsjnBqMwhlWTJTcm.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/y51M7Ca95sCXTCDvJaRP1uzxKbg.jpg', "overview"='In year 1250 B.C. during the late Bronze age, two emerging nations begin to clash. Paris, the Trojan prince, convinces Helen, Queen of Sparta, to leave her husband Menelaus, and sail with him back to Troy. After Menelaus finds out that his wife was taken by the Trojans, he asks his brother Agamemnon to help him get her back. Agamemnon sees this as an opportunity for power. They set off with 1,000 ships holding 50,000 Greeks to Troy.', "external_url"=NULL, "platforms"=NULL, "popularity"=60.2621, "vote_average"=7.182, "is_ambiguous"=0, "evidence_score"=1.34780000000000015e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-12 02:31:31' WHERE "id"=3325;
