UPDATE "recommendations" SET "tmdb_id"=32567, "imdb_id"='tt0264578', "igdb_id"=NULL, "title"='The Endurance', "original_title"='The Endurance - Shackleton''s Legendary Antarctic Expedition', "media_type"='movie', "release_year"=2000, "poster_url"='https://image.tmdb.org/t/p/w500/7zWvRlfnDTbmcGw8F28PEx7KX2k.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/bbCygAkvqSc0hWdn1Iiv574J0H7.jpg', "overview"='Documentary on the Shackleton Antartic expedition. A retelling of Sir Ernest Shackleton''s ill-fated expedition to Antarctica in and the crew of his vessel ''The Endurance'', which was trapped in the ice floes and frigid open ocean of the Antarctic in 1914. Shackleton decided, with many of his crew injured and weak from exposure and starvation, to take a team of his fittest men and attempt to find help. Setting out in appalling conditions with hopelessly inadequate equipment, they endured all weather and terrain and finally reached safety. Persuading a local team of his confidence that the abandoned team would still be alive, he set out again to find them. After almost 2 years trapped on the ice, all members of the crew were finally rescued.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.3713, "vote_average"=6.967, "is_ambiguous"=0, "evidence_score"=4.58, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-12 02:31:31' WHERE "id"=3669;
