UPDATE "recommendations" SET "tmdb_id"=11662, "imdb_id"='tt0405821', "igdb_id"=NULL, "title"='Casshern', "original_title"='CASSHERN', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/naIjHWfQFge69GqeehgsekwDkbl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nOovQqWWrGRkEkefR19syGO5a9i.jpg', "overview"='Fifty years of war between the Great Eastern Federation and Europa - now merged as Eurasia - have taken their toll on planet Earth. As a result of the use of biological, chemical and nuclear weapons, much of Earth has become uninhabitable and people have become prey to new diseases. Professor Azuma''s "neo-cell" project, which is supposed to be the answer to mankind''s hardships, becomes a nightmare come true when mutants spawned from the experiment escape and declare war on the human race. Azuma''s son Tetsuya, who was killed during the previous war, is reborn into the cyborg Casshern as mankind''s last hope against the new mutant threat. This live-action sci-fi movie based on a 1973 Japanese animé of the same name.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.8794, "vote_average"=5.895, "is_ambiguous"=0, "evidence_score"=4.025, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-12 02:31:31' WHERE "id"=5622;
