UPDATE "recommendations" SET "tmdb_id"=16180, "imdb_id"='tt0070294', "igdb_id"=NULL, "title"='The Legend of Hell House', "original_title"='The Legend of Hell House', "media_type"='movie', "release_year"=1973, "poster_url"='https://image.tmdb.org/t/p/w500/zfTWQD3UWJNlv44VLljjLcU3hWA.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nuDpIsAWww6MhBLE0LKlbeyb5J9.jpg', "overview"='A team consisting of a physicist, his wife, a young female psychic, and the only survivor of the previous visit are sent to the notorious Hell House to prove or disprove survival after death. Previous visitors have either been killed or gone mad, and it is up to the team to survive a full week in isolation, and solve the mystery of the Hell House.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.3074, "vote_average"=6.667, "is_ambiguous"=0, "evidence_score"=2.01, "created_at"='2026-08-09 02:29:31', "updated_at"='2026-08-12 02:31:31' WHERE "id"=8715;
UPDATE "recommendations" SET "tmdb_id"=9825, "imdb_id"='tt0139414', "igdb_id"=NULL, "title"='Lake Placid', "original_title"='Lake Placid', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/pEszakCP8j9E9S0UPLfEa3Cad3O.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/vvXc5WOBJQa3igNffSxMsqYyoqy.jpg', "overview"='When a man is eaten alive by an unknown creature, the local Game Warden teams up with a paleontologist from New York to find the beast. Add to the mix an eccentric philanthropist with a penchant for "Crocs", and here we go! This quiet, remote lake is suddenly the focus of an intense search for a crocodile with a taste for live animals...and people!', "external_url"=NULL, "platforms"=NULL, "popularity"=7.0908, "vote_average"=5.937, "is_ambiguous"=0, "evidence_score"=9.14, "created_at"='2026-08-09 02:29:31', "updated_at"='2026-08-12 02:31:31' WHERE "id"=8727;
UPDATE "recommendations" SET "tmdb_id"=9822, "imdb_id"='tt0120751', "igdb_id"=NULL, "title"='Mighty Joe Young', "original_title"='Mighty Joe Young', "media_type"='movie', "release_year"=1998, "poster_url"='https://image.tmdb.org/t/p/w500/jM39MOyLOxCD6Njz4vfQkGaKkY1.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/dkNjhkEk2tw7hoxx7Ik1YQsdenZ.jpg', "overview"='As a child living in Africa, Jill Young saw her mother killed while protecting wild gorillas from poachers led by Andrei Strasser. Now an adult, Jill cares for an orphaned gorilla named Joe -- who, due to a genetic anomaly, is 15 feet tall. When Gregg O''Hara arrives from California and sees the animal, he convinces Jill that Joe would be safest at his wildlife refuge. But Strasser follows them to the U.S., intent on capturing Joe for himself.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.4031, "vote_average"=6.319, "is_ambiguous"=0, "evidence_score"=6.02, "created_at"='2026-08-09 02:29:31', "updated_at"='2026-08-12 02:31:31' WHERE "id"=8747;
UPDATE "recommendations" SET "tmdb_id"=11532, "imdb_id"='tt0089087', "igdb_id"=NULL, "title"='The Emerald Forest', "original_title"='The Emerald Forest', "media_type"='movie', "release_year"=1985, "poster_url"='https://image.tmdb.org/t/p/w500/fdRlqPnPFaPyQqS3KiBLJwWQPBe.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/8JH97RT7J2zMRDx3ia7wwywkIwV.jpg', "overview"='For ten years, engineer Bill Markham has searched tirelessly for his son Tommy who disappeared from the edge of the Brazilian rainforest. Miraculously, he finds the boy living among the reclusive Amazon tribe who adopted him. And that''s when Bill''s adventure truly begins. For his son is now a grown tribesman who moves skillfully through this beautiful-but-dangerous terrain, fearful only of those who would exploit it. And as Bill attempts to "rescue" him from the savagery of the untamed jungle, Tommy challenges Bill''s idea of true civilization and his notions about who needs rescuing.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.3836, "vote_average"=6.603, "is_ambiguous"=0, "evidence_score"=6.51, "created_at"='2026-08-09 02:29:31', "updated_at"='2026-08-12 02:31:31' WHERE "id"=8750;
