UPDATE "recommendations" SET "tmdb_id"=13958, "imdb_id"='tt0923752', "igdb_id"=NULL, "title"='The King of Kong: A Fistful of Quarters', "original_title"='The King of Kong: A Fistful of Quarters', "media_type"='movie', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/wACtXGiO08EBbJhqsD2nUzPsrKe.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cXN62FQwOoBcKlIJ9uE3Cn5wHAc.jpg', "overview"='In this hilarious arcade showdown, a humble novice goes head-to-head against the reigning Donkey Kong champ in a confrontation that rocks the gaming world to its processors! For over 20 years, Billy Mitchell has owned the throne of the Donkey Kong world. No one could beat his top score until now. Newcomer Steve Wiebe claims to have beaten the unbeatable, but Mitchell isn''t ready to relinquish his crown without a fight. Go behind the barrels as the two battle it out in a vicious war to earn the title of the true King of Kong.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.5507, "vote_average"=7.733, "is_ambiguous"=0, "evidence_score"=5.765, "created_at"='2026-08-11 22:09:33', "updated_at"='2026-08-12 02:31:31' WHERE "id"=9450;
