UPDATE "recommendations" SET "tmdb_id"=57978, "imdb_id"='tt0082727', "igdb_id"=NULL, "title"='Meantime', "original_title"='Meantime', "media_type"='movie', "release_year"=1983, "poster_url"='https://image.tmdb.org/t/p/w500/aYeCvrkgUCylSQwmMFcqXV27WvD.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/aWelzaq3cmOWPCQV3rgZmPiTakW.jpg', "overview"='A working-class family in London''s East End is struggling to stay afloat during the recession under Prime Minister Margaret Thatcher''s premiership. Only the mother Mavis is working; father Frank and the couple''s two sons Colin, a timid, chronically shy individual and Mark, an outspoken, headstrong young man, are on the dole. This situation is contrasted by the presence of Mavis''s sister Barbara, and her husband John, whose financial and social loftiness appears to be a comfortable facade over the unspoken soreness of a lackluster marriage.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.8551, "vote_average"=6.7, "is_ambiguous"=0, "evidence_score"=2.145, "created_at"='2026-08-11 22:09:33', "updated_at"='2026-08-12 02:31:31' WHERE "id"=9492;
